package com.hospital.system.service; import com.hospital.system.model.Patient; import com.hospital.system.repository.PatientRepository; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*; @Service public class PatientService {private final PatientRepository r; public PatientService(PatientRepository r){this.r=r;} public List<Patient> all(String q){return r.all(q);} public Patient one(Long id){return r.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Patient not found"));} public Patient add(Patient p){if(p.fullName==null||p.fullName.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Full name is required");r.add(p);return r.all(p.fullName).get(0);} public Patient update(Long id,Patient p){one(id);r.update(id,p);return one(id);} public void delete(Long id){one(id);r.delete(id);} }
